// Continuous standup digest -- runs every 5 minutes via cron (or on-demand
// via /webhook/digest-fire). INCREMENTAL: each sweep reads only the family
// voices captured SINCE the last sweep, using a high-water-mark state file.
// This is the continuous-feedback-reel refactor (2026-06-03): feedback ->
// upgrade lag drops from ~24h to ~5 min. Sources:
//   - /data/finance-events/family-feedback/  (Suggest button submissions)
//   - /data/chatin/                          (@nas / @cpoe / @christiana)
// Summarizes via Ollama 14b. Posts to Synology Chat + ntfy family channel.
//
// MATERIAL-ONLY-FIRE: a sweep with zero new voices writes state and returns
// silently -- NO ntfy. At 288 sweeps/day a quiet ping would be spam. Only a
// sweep that actually has new family voices pushes a notification.
//
// IDEMPOTENT: the window is [last_processed_at, sweep_start). State advances
// to sweep_start on every sweep (quiet or material), so no voice is processed
// twice and none is skipped. First run (no state) falls back to a 24h window.
//
// Per BUSINESS-PROCESS-CONNECTIONS Family-Voice-Is-The-Connection: every
// voice gets acknowledged fast. This is the continuous side of that promise.
// Per AI-FOUNDATION-INTERNAL-OPERATIONS: summarization is Ollama-14b's job
// (sovereign, free). Claude only escalates when a voice needs code work.
// Per TLC firewall: family voices stay on the NAS (Ollama + Synology + ntfy).

const fs = require('fs');
const path = require('path');

const FEEDBACK_DIR = '/data/finance-events/family-feedback';
const CHATIN_DIR = '/data/chatin';
const STATE_FILE = '/data/finance-events/family-feedback/_digest_state.json';
const OLLAMA_BASE = 'http://ollama:11434';
const OLLAMA_MODEL = 'qwen2.5:14b-instruct-q4_K_M';
const NTFY_BASE = 'http://ntfy:80';
const NTFY_TOPIC = 'poetech-family-feedback';
const FIRST_RUN_FALLBACK_MS = 24 * 60 * 60 * 1000;

function safeReadDir(dir) {
  try { return fs.readdirSync(dir); } catch (_) { return []; }
}
function safeReadJson(p) {
  try { return JSON.parse(fs.readFileSync(p, 'utf8')); } catch (_) { return null; }
}

// High-water mark for this sweep. The window is [since, sweepStartMs): voices
// captured at or after sweepStartMs are left for the next sweep, so a voice
// landing mid-sweep is never lost and never double-counted.
const sweepStart = new Date();
const sweepStartMs = sweepStart.getTime();
const sweepStartIso = sweepStart.toISOString();

// Resolve the start of the window from the state file. First run (no state or
// unreadable) falls back to a 24h window so the first sweep is not empty.
const state = safeReadJson(STATE_FILE);
let since;
if (state && state.last_processed_at) {
  const t = new Date(state.last_processed_at).getTime();
  since = isNaN(t) ? (sweepStartMs - FIRST_RUN_FALLBACK_MS) : t;
} else {
  since = sweepStartMs - FIRST_RUN_FALLBACK_MS;
}

function writeState(voiceCount) {
  try {
    fs.mkdirSync(FEEDBACK_DIR, { recursive: true });
    fs.writeFileSync(STATE_FILE, JSON.stringify({
      last_processed_at: sweepStartIso,
      updated_at: sweepStartIso,
      last_voice_count: voiceCount
    }, null, 2));
  } catch (_) {}
}

function inWindow(capturedAt) {
  const t = new Date(capturedAt).getTime();
  return !isNaN(t) && t >= since && t < sweepStartMs;
}

// Collect feedback (Suggest button submissions) in the window.
const feedback = [];
for (const fn of safeReadDir(FEEDBACK_DIR)) {
  if (!fn.endsWith('.json') || fn.startsWith('_')) continue;
  const rec = safeReadJson(path.join(FEEDBACK_DIR, fn));
  if (!rec || !rec.captured_at) continue;
  if (!inWindow(rec.captured_at)) continue;
  feedback.push(rec);
}
feedback.sort((a, b) => a.captured_at.localeCompare(b.captured_at));

// Collect chat messages in the window.
const chats = [];
for (const fn of safeReadDir(CHATIN_DIR)) {
  if (!fn.endsWith('.json') || fn.startsWith('_')) continue;
  const rec = safeReadJson(path.join(CHATIN_DIR, fn));
  if (!rec || !rec.captured_at) continue;
  if (!inWindow(rec.captured_at)) continue;
  chats.push(rec);
}
chats.sort((a, b) => a.captured_at.localeCompare(b.captured_at));

const totalVoices = feedback.length + chats.length;

if (totalVoices === 0) {
  // MATERIAL-ONLY-FIRE: quiet sweep. Advance the high-water mark and return
  // silently. No ntfy -- 288 quiet pings/day would be spam. The webhook path
  // still gets a JSON response so an on-demand fire is never confusing.
  writeState(0);
  return [{ json: { ok: true, voice_count: 0, quiet: true, window_start: new Date(since).toISOString(), window_end: sweepStartIso } }];
}

// Build the Ollama prompt for summarization.
const voicesText = [
  feedback.length ? '## Suggest button submissions (' + feedback.length + ')' : '',
  ...feedback.map(f => '- [' + f.sender + ' / ' + f.type + (f.screen_context && f.screen_context.path ? ' on ' + f.screen_context.path : '') + '] ' + f.message),
  chats.length ? '\n## Chat thoughts (' + chats.length + ')' : '',
  ...chats.map(c => '- [' + c.sender + '] ' + (c.text || c.raw_text || '').slice(0, 400))
].filter(Boolean).join('\n');

const prompt = `You are the continuous digest generator for the PoeTech Family OS Foundation Agent.

The team needs a 5-7 sentence summary of the family voices captured since the last sweep. Group by sender. Name actionable items. Note any patterns.

Direct tone, warm but not flowery. No emoji. No filler. Speak as the Foundation Agent.

Respect these family conventions:
- Refer to the family members by their handles (dpoe = Darrell, cpoe = Christina, christiana = Christiana).
- Distinguish 'feedback' (Suggest button) from 'thought' (@nas chat).
- Identify items that look like they need code work versus items that are conversational.

Family voices to summarize:

${voicesText}

Return ONLY the summary text. No preamble, no markdown header.`;

let summary = '';
try {
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: OLLAMA_BASE + '/api/generate',
    body: { model: OLLAMA_MODEL, prompt: prompt, stream: false, options: { temperature: 0.4, num_predict: 600 } },
    json: true,
    timeout: 120000
  });
  summary = (data.response || '').trim();
} catch (e) {
  summary = 'Ollama summarization failed: ' + String(e) + '. Raw voice count: ' + totalVoices + '. Review the feedback and chatin directories directly.';
}

const title = 'PoeTech feedback reel - ' + totalVoices + ' new voice' + (totalVoices === 1 ? '' : 's');

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: NTFY_BASE + '/' + NTFY_TOPIC,
    headers: { 'Title': title, 'Priority': '4', 'Tags': 'speech_balloon', 'Content-Type': 'text/plain' },
    body: summary,
    timeout: 5000
  });
} catch (_) {}

// Advance the high-water mark only AFTER the material sweep has done its work.
writeState(totalVoices);

return [{ json: { ok: true, voice_count: totalVoices, feedback_count: feedback.length, chat_count: chats.length, window_start: new Date(since).toISOString(), window_end: sweepStartIso, summary } }];
